        return 1;
    }
    size_t n = strlen(argv[1]);
    char m[2 * n + 1];

    for (size_t i = 0; i < n; i++) {
        m[i] = argv[1][i];               // left half: forwards
        m[2 * n - 1 - i] = argv[1][i];   // right half: backwards
    }
    m[2 * n] = '\0';

    printf("%s\n", m);
    return 0;
}

