#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s word\n", argv[0]);
        return 1;
    }
    size_t n = strlen(argv[1]);
    char t[2 * n + 1];
    size_t k = 0;                  // next free index in t
    for (size_t i = 0; i < n; i++) {
        if (i > 0) {
            t[k] = '-';
            k++;
        }
        t[k] = argv[1][i];
        k++;
    }
    t[k] = '\0';
    printf("%s\n", t);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s text\n", argv[0]);
        return 1;
    }
    size_t n = strlen(argv[1]);
    char t[n + 1];
    for (size_t i = 0; i < n; i++) {
        if (argv[1][i] == ' ') {
            t[i] = '_';
        } else {
            t[i] = argv[1][i];
        }
    }
    t[n] = '\0';
    puts(t);
    return 0;
}
